The postcondition computes the expected list independently. It walks `xs` and appends each value the first time it appears. It then requires `result` to match that list exactly in length, values and order. Membership is checked with an explicit loop rather than `in`, because `in` is not in the verifier's listed subset.

```python
def pre(xs):
    return True


def _contains(lst, v):
    for y in lst:
        if y == v:
            return True
    return False


def _expected(xs):
    out = []
    for x in xs:
        if not _contains(out, x):
            out.append(x)
    return out


def post(xs, result):
    exp = _expected(xs)
    if len(result) != len(exp):
        return False
    for i in range(len(exp)):
        if result[i] != exp[i]:
            return False
    return True
```
